'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Float32Array = require( '@stdlib/array/float32' );
var res2json = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof res2json, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function serializes a results object to JSON', function test( t ) {
	var expected;
	var actual;
	var value;

	value = {
		'rejected': true,
		'alpha': 0.05,
		'pValue': 0.0031,
		'statistic': 4.0,
		'df': 9.0,
		'nullValue': 0.0,
		'mean': 1.2,
		'sd': 0.3,
		'ci': new Float64Array( [ 0.5214, 1.8786 ] ),
		'alternative': 'two-sided',
		'method': 'One-sample t-test'
	};

	expected = {
		'rejected': true,
		'alpha': 0.05,
		'pValue': 0.0031,
		'statistic': 4.0,
		'df': 9.0,
		'nullValue': 0.0,
		'mean': 1.2,
		'sd': 0.3,
		'ci': {
			'type': 'Float64Array',
			'data': [ 0.5214, 1.8786 ]
		},
		'alternative': 'two-sided',
		'method': 'One-sample t-test'
	};

	actual = res2json( value );
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function serializes a results object to JSON (float32)', function test( t ) {
	var expected;
	var actual;
	var value;
	var ci;

	ci = new Float32Array( [ 0.5214, 1.8786 ] );
	value = {
		'rejected': false,
		'alpha': 0.01,
		'pValue': 0.0031,
		'statistic': 4.0,
		'df': 9.0,
		'nullValue': 0.0,
		'mean': 1.2,
		'sd': 0.3,
		'ci': ci,
		'alternative': 'greater',
		'method': 'One-sample t-test'
	};

	expected = {
		'rejected': false,
		'alpha': 0.01,
		'pValue': 0.0031,
		'statistic': 4.0,
		'df': 9.0,
		'nullValue': 0.0,
		'mean': 1.2,
		'sd': 0.3,
		'ci': {
			'type': 'Float32Array',
			'data': [ ci[ 0 ], ci[ 1 ] ]
		},
		'alternative': 'greater',
		'method': 'One-sample t-test'
	};

	actual = res2json( value );
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
